/* @lc app=leetcode id=1687 lang=kotlin */ class Solution { fun boxDelivering(boxes: Array<IntArray>, portsCount: Int, maxBoxes: Int, maxWeight: Int): Int = IntArray(boxes.size + 2).let { diff -> LongArray(boxes.size + 2).let { W -> IntArray(boxes.size + 2).let { dp -> IntArray(boxes.size + 2).let { q -> IntArray(2).let { ptr -> (0 until boxes.size).forEach { i -> diff[i + 1] = (diff[i] + if (i > 0 && boxes[i][0] != boxes[i - 1][0]) 1 else 0).also { W[i + 1] = W[i] + boxes[i][1] } }.also { q[0] = 0 }.also { ptr[1] = 1 }.run { (1..boxes.size).forEach { i -> ptr.also { while (ptr[0] < ptr[1] && (i - q[ptr[0]] > maxBoxes || W[i] - W[q[ptr[0]]] > maxWeight)) ptr[0]++ }.also { dp[i] = diff[i] + 2 + dp[q[ptr[0]]] - diff[q[ptr[0]] + 1] }.also { while (ptr[0] < ptr[1] && dp[i] - diff[i + 1] <= dp[q[ptr[1] - 1]] - diff[q[ptr[1] - 1] + 1]) ptr[1]-- }.also { q[ptr[1]++] = i } } }.run { dp[boxes.size] } } } } } } }